#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[555],b[555];
bool vis[555];
struct node{
	int x,y;
	double z;
};
vector<node>v;
int f[555];
int find(int x){
	if(f[x]!=x){
		return f[x]=find(f[x]);
	}else{
		return x;
	}
}
bool cmp(node x,node y){
	return x.z<y.z;
}
signed main(){
	int n,l;
	cin>>n>>l;
	for(int i=1;i<=n;i++){
		cin>>a[i]>>b[i];
	}

	for(int i=1;i<=n;i++){
		for(int j=i+1;j<=n;j++){
			int x=a[i]-a[j];
			int y=b[i]-b[j];
			x*=x;
			y*=y;
			double g=sqrt(x+y);
			if(g<=l){
				v.push_back({i,j,g});
			}
		}
	}
	sort(v.begin(),v.end(),cmp);
	double ans=0.0;
	int ff=1,sum=0;
	for(int i=1;i<=n;i++){
		f[i]=i;
	}
	for(int i=0;i<v.size();i++){
		int x=v[i].x,y=v[i].y;
		double z=v[i].z;
//		cout<<x<<" "<<y<<" "<<z<<endl;
		int fx=find(x),fy=find(y);
		if(fx!=fy){
			f[fx]=fy;
			ans+=z;
			ff=0;
			sum++;
		}
	}
	if(sum!=n-1){
		cout<<"Impossible";
		return 0;
	}
	printf("%.2lf",ans);
	return 0;
}
